import{_ as a,o as l,c as n,aw as o}from"./chunks/framework.DLufY-ao.js";const A=JSON.parse(`{"title":"Оператор объединения с null '??'","description":"","frontmatter":{},"headers":[],"relativePath":"js/js/es6+/nullish-coalescing-operator.md","filePath":"wiki/dev-commit/js/js/es6+/nullish-coalescing-operator.md"}`),e={name:"js/js/es6+/nullish-coalescing-operator.md"};function p(t,s,c,r,i,y){return l(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="оператор-объединения-с-null" tabindex="-1">Оператор объединения с null &#39;??&#39; <a class="header-anchor" href="#оператор-объединения-с-null" aria-label="Permalink to &quot;Оператор объединения с null &#39;??&#39;&quot;">​</a></h1><h2 id="теория" tabindex="-1">Теория <a class="header-anchor" href="#теория" aria-label="Permalink to &quot;Теория&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="https://learn.javascript.ru/nullish-coalescing-operator" target="_blank" rel="noreferrer">https://learn.javascript.ru/nullish-coalescing-operator</a> - Learn JavaScript</li></ul></div><ul><li>Выражение «определено», если оно отличается от <em>null</em> или <em>undefined</em></li><li>Оператор <code>??</code> позволяет выбрать первое «определённое» значение из списка, если оно НЕ <em>null/undefined</em></li><li>Используется для присвоения переменным значений по умолчанию</li></ul><p><strong>Результат выражения <code>a ?? b</code> будет следующим:</strong></p><ul><li><code>a</code>, если значение <code>a</code> определено</li><li><code>b</code>, если значение <code>a</code> не определено</li></ul><h2 id="варианты" tabindex="-1">Варианты <a class="header-anchor" href="#варианты" aria-label="Permalink to &quot;Варианты&quot;">​</a></h2><h3 id="сравнение-с" tabindex="-1">Сравнение с <code>||</code> <a class="header-anchor" href="#сравнение-с" aria-label="Permalink to &quot;Сравнение с \`||\`&quot;">​</a></h3><ul><li><code>||</code> - возвращает первое истинное значение</li><li><code>??</code> - возвращает первое определённое значение</li></ul><h3 id="ложные-значения" tabindex="-1">Ложные значения <a class="header-anchor" href="#ложные-значения" aria-label="Permalink to &quot;Ложные значения&quot;">​</a></h3><ul><li>Оператор <em>||</em> не различает <em>false</em>, <em>0</em>, <em>пустую строку</em>, <em>null/undefined</em>. Для него они все одинаковые, т.е. являются ложными значениями. Если первым аргументом для оператора <em>||</em> будет любое из перечисленных значений, то в качестве результата получим второй аргумент</li><li>Однако на практике часто требуется использовать значение по умолчанию только тогда, когда переменная является <em>null/undefined</em></li></ul><div class="language-js"><button title="Скопировать код" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> height</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 0</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(height </span><span style="color:#0184BC;">||</span><span style="color:#986801;"> 100</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// 100</span></span>
<span class="line"><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(height </span><span style="color:#0184BC;">??</span><span style="color:#986801;"> 100</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// 0</span></span></code></pre></div><h3 id="приоритет" tabindex="-1">Приоритет <a class="header-anchor" href="#приоритет" aria-label="Permalink to &quot;Приоритет&quot;">​</a></h3><ul><li>Оператор <code>??</code> имеет довольно низкий приоритет: <em>5</em>, согласно <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Operators/Operator_Precedence#table" target="_blank" rel="noreferrer">таблице на MDN</a></li><li>Оператор <code>??</code> вычисляется до <code>=</code> и <code>?</code>, но после большинства других операций, таких как <code>+</code>, <code>*</code></li><li>Из этого следует, что если нужно выбрать значение при помощи оператора <code>??</code> вместе с другими операторами в выражении, следует добавить круглые скобки</li></ul><div class="language-js"><button title="Скопировать код" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> height</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> null</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> width</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> null</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Важно: используйте круглые скобки</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> area</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> (height </span><span style="color:#0184BC;">??</span><span style="color:#986801;"> 100</span><span style="color:#383A42;">) </span><span style="color:#0184BC;">*</span><span style="color:#383A42;"> (width </span><span style="color:#0184BC;">??</span><span style="color:#986801;"> 50</span><span style="color:#383A42;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(area); </span><span style="color:#A0A1A7;font-style:italic;">// 5000</span></span></code></pre></div><ul><li>Иначе, если опустить скобки, то оператор <code>*</code> выполнится первым, так как у него приоритет выше, чем у <code>??</code>, а это приведёт к неправильным результатам</li></ul><div class="language-js"><button title="Скопировать код" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// Без круглых скобок</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> area</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> height </span><span style="color:#0184BC;">??</span><span style="color:#986801;"> 100</span><span style="color:#0184BC;"> *</span><span style="color:#383A42;"> width </span><span style="color:#0184BC;">??</span><span style="color:#986801;"> 50</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// ...то же самое, что предыдущее выражение (вероятно, это не то, что нам нужно):</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> area</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> height </span><span style="color:#0184BC;">??</span><span style="color:#383A42;"> (</span><span style="color:#986801;">100</span><span style="color:#0184BC;"> *</span><span style="color:#383A42;"> width) </span><span style="color:#0184BC;">??</span><span style="color:#986801;"> 50</span><span style="color:#383A42;">;</span></span></code></pre></div><h2 id="использование-вместе-с-или" tabindex="-1">Использование <code>??</code> вместе с <code>&amp;&amp;</code> или <code>||</code> <a class="header-anchor" href="#использование-вместе-с-или" aria-label="Permalink to &quot;Использование \`??\` вместе с \`&amp;&amp;\` или \`||\`&quot;">​</a></h2><ul><li>По соображениям безопасности JavaScript запрещает использование оператора <em>??</em> вместе с <em>&amp;&amp;</em> и <em>||</em>, если только приоритет явно не указан в круглых скобках</li></ul><div class="language-js"><button title="Скопировать код" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> x</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> 1</span><span style="color:#0184BC;"> &amp;&amp;</span><span style="color:#986801;"> 2</span><span style="color:#0184BC;"> ??</span><span style="color:#986801;"> 3</span><span style="color:#383A42;">; </span><span style="color:#A0A1A7;font-style:italic;">// Синтаксическая ошибка</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> x</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> (</span><span style="color:#986801;">1</span><span style="color:#0184BC;"> &amp;&amp;</span><span style="color:#986801;"> 2</span><span style="color:#383A42;">) </span><span style="color:#0184BC;">??</span><span style="color:#986801;"> 3</span><span style="color:#383A42;">; </span><span style="color:#A0A1A7;font-style:italic;">// Работает без ошибок</span></span>
<span class="line"><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(x); </span><span style="color:#A0A1A7;font-style:italic;">// 2</span></span></code></pre></div><h2 id="примеры" tabindex="-1">Примеры <a class="header-anchor" href="#примеры" aria-label="Permalink to &quot;Примеры&quot;">​</a></h2><h3 id="пример-1" tabindex="-1">Пример #1 <a class="header-anchor" href="#пример-1" aria-label="Permalink to &quot;Пример #1&quot;">​</a></h3><div class="language-js"><button title="Скопировать код" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// Будет height=100, если переменная height равна null или undefined</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> height</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> height </span><span style="color:#0184BC;">??</span><span style="color:#986801;"> 100</span><span style="color:#383A42;">;</span></span></code></pre></div><h3 id="пример-2" tabindex="-1">Пример #2 <a class="header-anchor" href="#пример-2" aria-label="Permalink to &quot;Пример #2&quot;">​</a></h3><div class="language-js"><button title="Скопировать код" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;">// Через ??</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> result</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> a </span><span style="color:#0184BC;">??</span><span style="color:#383A42;"> b;</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Через тернарный оператор</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> result</span><span style="color:#0184BC;"> =</span><span style="color:#383A42;"> a </span><span style="color:#0184BC;">!==</span><span style="color:#986801;"> null</span><span style="color:#0184BC;"> &amp;&amp;</span><span style="color:#383A42;"> a </span><span style="color:#0184BC;">!==</span><span style="color:#986801;"> undefined</span><span style="color:#0184BC;"> ?</span><span style="color:#383A42;"> a </span><span style="color:#0184BC;">:</span><span style="color:#383A42;"> b;</span></span></code></pre></div><h3 id="пример-3" tabindex="-1">Пример #3 <a class="header-anchor" href="#пример-3" aria-label="Permalink to &quot;Пример #3&quot;">​</a></h3><ul><li>Можно записать последовательность из операторов <em>??</em>, чтобы получить первое значение из списка, которое не является <em>null/undefined</em></li></ul><div class="language-js"><button title="Скопировать код" class="copy"></button><span class="lang">js</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> firstName</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> null</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> lastName</span><span style="color:#0184BC;"> =</span><span style="color:#986801;"> null</span><span style="color:#383A42;">;</span></span>
<span class="line"><span style="color:#A626A4;">const</span><span style="color:#986801;"> nickName</span><span style="color:#0184BC;"> =</span><span style="color:#50A14F;"> &quot;Суперкодер&quot;</span><span style="color:#383A42;">;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Показывает первое определённое значение</span></span>
<span class="line"></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Через ??</span></span>
<span class="line"><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(firstName </span><span style="color:#0184BC;">??</span><span style="color:#383A42;"> lastName </span><span style="color:#0184BC;">??</span><span style="color:#383A42;"> nickName </span><span style="color:#0184BC;">??</span><span style="color:#50A14F;"> &quot;Аноним&quot;</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// Суперкодер</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;">// Через ||</span></span>
<span class="line"><span style="color:#383A42;">console.</span><span style="color:#4078F2;">log</span><span style="color:#383A42;">(firstName </span><span style="color:#0184BC;">||</span><span style="color:#383A42;"> lastName </span><span style="color:#0184BC;">||</span><span style="color:#383A42;"> nickName </span><span style="color:#0184BC;">||</span><span style="color:#50A14F;"> &quot;Аноним&quot;</span><span style="color:#383A42;">); </span><span style="color:#A0A1A7;font-style:italic;">// Суперкодер</span></span></code></pre></div>`,28)])])}const h=a(e,[["render",p]]);export{A as __pageData,h as default};
